$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
if(@(Get-Process swift,swiftc,swift-build,clang,FactoryProbe -ErrorAction SilentlyContinue).Count){throw 'compiler/native lane busy'}
$OS=Get-CimInstance -ClassName Win32_OperatingSystem;if([int64]$OS.FreePhysicalMemory -lt 8388608){throw 'less than8GiB available for bounded2GiB test compiler'}
$Root='D:\Claude\swiftright\.factory-work\runtime-stage\api-image-body-r1'
$Runtime=Join-Path $Root 'runtime';$Scratch=Join-Path $Root 'scratch-xcode-r7'

$Delta=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))|ConvertFrom-Json
$Retired=Join-Path $Root 'retired-api-r7';if(Test-Path -LiteralPath $Retired){throw 'fresh retirement required'}
foreach($F in $Delta){$P=Join-Path $Runtime $F.path;if((Get-FileHash -LiteralPath $P).Hash.ToLowerInvariant() -cne $F.oldHash){throw 'old source drift'};$Dest=Join-Path $Retired $F.path;New-Item -ItemType Directory -Path (Split-Path -Parent $Dest) -Force|Out-Null;Move-Item -LiteralPath $P -Destination $Dest;[IO.File]::WriteAllBytes($P,[Convert]::FromBase64String($F.base64))}
$Rows=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))|ConvertFrom-Json
foreach($Row in $Rows){$P=Join-Path $Runtime $Row.path;if((Get-Item -LiteralPath $P).Length -ne $Row.bytes -or (Get-FileHash -LiteralPath $P).Hash.ToLowerInvariant() -cne $Row.sha256){throw ('runtime source drift: '+$Row.path)}}
if(@(Get-ChildItem -LiteralPath $Runtime -File -Recurse).Count -ne $Rows.Count){throw 'extra runtime source files'}
$env:SDKROOT='C:\Users\adrds\AppData\Local\Programs\Swift\Platforms\6.4.0\Windows.platform\Developer\SDKs\Windows.sdk'
$env:Path='C:\Users\adrds\AppData\Local\Programs\Swift\Platforms\6.4.0\Windows.platform\Developer\Library\XCTest-6.4.0\usr\bin64;C:\Users\adrds\AppData\Local\Programs\Swift\Platforms\6.4.0\Windows.platform\Developer\Library\Testing-6.4.0\usr\bin64;C:\Users\adrds\AppData\Local\Programs\Swift\Runtimes\6.4.0\usr\bin;'+$env:Path
$Swift='C:\Users\adrds\AppData\Local\Programs\Swift\Toolchains\6.4.0+Asserts\usr\bin\swift.exe'
if((Get-FileHash -LiteralPath $Swift).Hash.ToLowerInvariant() -cne '1e406093ba7ca843cfcfab9b6efc72c23bb67a621f2925802196d5891e642d1a'){throw 'compiler drift'}
if(-not(Test-Path -LiteralPath $Scratch)){throw 'qualified existing R7 release scratch required'}
& $Swift test -c release --package-path $Runtime --scratch-path $Scratch --jobs 1 -Xswiftc -j1 -Xswiftc -num-threads -Xswiftc 1
$Result=$LASTEXITCODE;if($null -eq $Result){throw 'Swift exit code missing'};exit ([int]$Result)
